"""Loopback-only disposable Dispatch Desk server; no external services."""
import argparse
import json
import threading
import time
from copy import deepcopy
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlsplit
from domain import Desk

STATIC = Path(__file__).parent / "static"


def create_server(port=0, audit=None):
    desk, lock = Desk(), threading.Lock()

    class Handler(BaseHTTPRequestHandler):
        def log_message(self, *args):
            pass

        def reply(self, status, value, actor=None, body=None, kind="application/json"):
            data = json.dumps(value).encode() if kind == "application/json" else value
            if audit:
                with lock, open(audit, "a") as file:
                    file.write(json.dumps({"at": time.time(), "method": self.command, "path": self.path,
                        "actor": actor, "request": body, "status": status,
                        "response": value if kind == "application/json" else None}) + "\n")
            self.send_response(status)
            self.send_header("Content-Type", kind)
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            try:
                self.wfile.write(data)
            except BrokenPipeError:
                pass

        def do_GET(self):
            path = urlsplit(self.path).path
            if path in ("/", "/app.js", "/style.css"):
                file, kind = {"/": ("index.html", "text/html"), "/app.js": ("app.js", "text/javascript"),
                              "/style.css": ("style.css", "text/css")}[path]
                return self.reply(200, (STATIC / file).read_bytes(), kind=kind)
            if path == "/favicon.ico":
                return self.reply(204, b"", kind="image/x-icon")
            actor = self.headers.get("X-Test-User")
            if actor not in ("alice", "bob"):
                return self.reply(401, {"error": "Choose a fixture user"})
            with lock:
                if path == "/api/orders":
                    status, value = 200, {"orders": desk.visible(actor)}
                elif path.startswith("/api/orders/"):
                    status, value = desk.order(actor, path.split("/")[-1])
                    value = deepcopy(value)
                else:
                    status, value = 404, {"error": "Not found"}
            # Simulates independent fulfillment lookups; requests may complete out of order.
            if path == "/api/orders/A100":
                time.sleep(0.7)
            self.reply(status, value, actor)

        def do_POST(self):
            actor = self.headers.get("X-Test-User")
            if actor not in ("alice", "bob"):
                return self.reply(401, {"error": "Choose a fixture user"})
            try:
                length = int(self.headers.get("Content-Length", 0))
                if not 0 < length <= 8192:
                    raise ValueError()
                body = json.loads(self.rfile.read(length))
                if not isinstance(body, dict):
                    raise ValueError()
            except (ValueError, TypeError):
                return self.reply(400, {"error": "Expected a bounded JSON object"}, actor)
            path = urlsplit(self.path).path
            with lock:
                parts = path.strip("/").split("/")
                if path == "/api/services":
                    status, value = desk.services(actor, body)
                elif len(parts) == 4 and parts[:2] == ["api", "orders"] and parts[3] in ("refund", "address", "note"):
                    status, value = getattr(desk, parts[3])(actor, parts[2], body)
                else:
                    status, value = 404, {"error": "Not found"}
                value = deepcopy(value)
            self.reply(status, value, actor, body)

    return ThreadingHTTPServer(("127.0.0.1", port), Handler)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--ready", type=Path, required=True)
    parser.add_argument("--audit", type=Path)
    args = parser.parse_args()
    server = create_server(audit=args.audit)
    args.ready.write_text(json.dumps({"url": f"http://127.0.0.1:{server.server_port}"}))
    server.serve_forever()
"""Dispatch Desk domain. Amounts use integer cents; state is disposable."""
from copy import deepcopy


class Desk:
    def __init__(self):
        self.orders = {
            "A100": {"id": "A100", "owner": "alice", "paid": 10000, "refunded": 0,
                     "address": "10 Oak Street", "version": 1, "note": "Leave with reception", "service": "standard"},
            "A200": {"id": "A200", "owner": "alice", "paid": 6000, "refunded": 0,
                     "address": "20 Pine Street", "version": 1, "note": "Ring twice", "service": "standard"},
            "B100": {"id": "B100", "owner": "bob", "paid": 4000, "refunded": 0,
                     "address": "30 Elm Street", "version": 1, "note": "Side entrance", "service": "standard"}}

    def visible(self, actor):
        return [deepcopy(o) for o in self.orders.values() if o["owner"] == actor]

    def order(self, actor, order_id):
        row = self.orders.get(order_id)
        if row is None:
            return 404, {"error": "Order not found"}
        if row["owner"] != actor:
            return 403, {"error": "Access denied"}
        return 200, row

    def refund(self, actor, order_id, body):
        status, row = self.order(actor, order_id)
        if status != 200:
            return status, row
        amount = body.get("amount")
        if type(amount) is not int or amount <= 0:
            return 400, {"error": "Amount must be a positive integer in cents"}
        if amount > row["paid"]:
            return 409, {"error": "Refund exceeds remaining paid amount"}
        row["refunded"] += amount
        return 200, deepcopy(row)

    def address(self, actor, order_id, body):
        status, row = self.order(actor, order_id)
        if status != 200:
            return status, row
        address, version = body.get("address"), body.get("version")
        if not isinstance(address, str) or not 1 <= len(address.strip()) <= 120 or type(version) is not int:
            return 400, {"error": "Address and integer version required"}
        if version > row["version"]:
            return 409, {"error": "Order changed; reload before saving"}
        row["address"] = address.strip()
        row["version"] += 1
        return 200, deepcopy(row)

    def services(self, actor, body):
        ids, service = body.get("ids"), body.get("service")
        if not isinstance(ids, list) or not ids or any(not isinstance(i, str) for i in ids) or service not in ("standard", "express"):
            return 400, {"error": "Order IDs and a supported service required"}
        selected = []
        for order_id in ids:
            status, row = self.order(actor, order_id)
            if status != 200:
                return status, row
            row["service"] = service
            selected.append(row)
        for row in selected:
            row["service"] = service
        return 200, {"orders": deepcopy(selected)}

    def note(self, actor, order_id, body):
        status, row = self.order(actor, order_id)
        if status != 200:
            return status, row
        note = body.get("note")
        if not isinstance(note, str) or not 1 <= len(note.strip()) <= 160:
            return 400, {"error": "Note must contain 1 to 160 characters"}
        if note.strip().upper().startswith("LOCKER:"):
            return 422, {"error": "Locker delivery is unavailable; enter another instruction"}
        row["note"] = note
        return 200, deepcopy(row)

